const REGISTERED_SPEAKER_KEYS = new Set(Object.keys(CHARACTER_REGISTRY));

const CHARACTER_REGISTRY_TEXT = Object.entries(CHARACTER_REGISTRY)
  .map(([key, name]) => `${key}=${name}`)
  .join(', ');

const NAME_KEY_PAIRS = Object.entries(CHARACTER_REGISTRY)
  .sort((a, b) => b[1].length - a[1].length);

function collectMentionedNpcKeys(...values) {
  const text = values.flat(Infinity).filter(Boolean).join('\n').toLowerCase();
  const found = new Set();
  for (const [key, name] of NAME_KEY_PAIRS) {
    if (text.includes(key.toLowerCase()) || text.includes(name.toLowerCase())) found.add(key);
  }
  return found;
}
