// ===== BEGIN emotion.js =====
const EMOTION_EXPRESSIONS = new Set(['default','smile','blush','serious','angry','sad','shock']);
const THRESHOLD = { default:0.48, smile:0.42, blush:0.58, serious:0.38, angry:0.56, sad:0.52, shock:0.68 };
const clamp01 = (n) => Math.max(0, Math.min(1, Number(n) || 0));

function normalizePrev(row = {}) {
  return {
    current: EMOTION_EXPRESSIONS.has(row.current) ? row.current : 'default',
    intensity: clamp01(row.intensity),
    turnsHeld: Math.max(0, Number(row.turnsHeld || 0)),
    lastChangedTurn: Number.isFinite(Number(row.lastChangedTurn)) ? Number(row.lastChangedTurn) : -99,
    reason: String(row.reason || ''),
  };
}

function resolveOne(prev, detected, intensity, confidence, currentTurn) {
  detected = EMOTION_EXPRESSIONS.has(detected) ? detected : 'default';
  intensity = clamp01(intensity);
  confidence = clamp01(confidence || 0.65);
  const same = detected === prev.current;
  if (same) return { final: prev.current, changed:false, why:'same-tag' };
  if (confidence < 0.42) return { final: prev.current, changed:false, why:'low-confidence' };

  let need = THRESHOLD[detected] ?? 0.5;
  const gap = currentTurn - prev.lastChangedTurn;
  if (gap <= 1) need += 0.12; // 직전 턴에 바뀌었다면 쉽게 출렁이지 않음
  if (prev.current === 'serious' && detected === 'smile') need += 0.04;
  if (prev.current === 'angry' && detected === 'blush') need += 0.10;
  if (prev.current === 'sad' && detected === 'smile') need += 0.06;
  if (detected === 'shock' && intensity >= 0.82) need = Math.min(need, 0.72);
  if (intensity < need) return { final: prev.current, changed:false, why:`below-threshold:${need.toFixed(2)}` };
  return { final: detected, changed:true, why:'accepted' };
}

function resolveTurnEmotions(turn, saveState = {}) {
  const states = Object.fromEntries(Object.entries(saveState?.emotionStates || {}).map(([k,v]) => [k, normalizePrev(v)]));
  const currentTurn = Number(saveState?.turnNumber || 0) + 1;
  const updates = {};
  const changedThisTurn = new Set();

  turn.scene = (turn.scene || []).map((item) => {
    if (item?.kind !== 'dialogue' || !item?.speaker_key || !REGISTERED_SPEAKER_KEYS.has(item.speaker_key)) return item;
    const key = item.speaker_key;
    const prev = states[key] || normalizePrev();
    const detected = EMOTION_EXPRESSIONS.has(item.expression) ? item.expression : prev.current;
    const intensity = clamp01(item.emotion_intensity ?? (detected === 'default' ? 0.25 : 0.55));
    const confidence = clamp01(item.emotion_confidence ?? 0.65);
    let result = resolveOne(prev, detected, intensity, confidence, currentTurn);

    // 한 응답 안에서 같은 NPC가 여러 번 표정이 마구 바뀌는 현상 억제. 아주 강한 shock/angry만 예외.
    if (changedThisTurn.has(key) && result.changed && !(intensity >= 0.88 && ['shock','angry'].includes(detected))) {
      result = { final: prev.current, changed:false, why:'one-change-per-turn' };
    }

    const final = result.final;
    const next = {
      current: final,
      intensity: final === detected ? intensity : Math.max(0.25, prev.intensity * 0.85),
      turnsHeld: result.changed ? 0 : prev.turnsHeld + 1,
      lastChangedTurn: result.changed ? currentTurn : prev.lastChangedTurn,
      reason: String(item.emotion_reason || prev.reason || '').slice(0,220),
      detected,
      confidence,
      lastSeenTurn: currentTurn,
    };
    states[key] = next;
    updates[key] = { npc_key:key, previous:prev.current, detected, final, intensity, confidence, changed:result.changed, transition_reason:result.why, reason:next.reason, state:next };
    if (result.changed) changedThisTurn.add(key);
    return { ...item, display_expression: final, detected_expression: detected, emotion_transition: result.why };
  });

  turn.emotion_updates = Object.values(updates);
  return turn;
}
// ===== END emotion.js =====

// ===== BEGIN utils.js =====
const PRICES = {
  'gpt-5.6-luna': { input: 1, cached: 0.10, output: 6 },
  'gpt-5.6-terra': { input: 2.5, cached: 0.25, output: 15 },
  'gpt-5.6-sol': { input: 5, cached: 0.5, output: 30 },
};

const EXPRESSIONS = new Set(['default', 'smile', 'blush', 'serious', 'angry', 'sad', 'shock']);
const clamp = (n, min, max) => Math.min(max, Math.max(min, Number(n) || 0));
const arrays = (value, max) => Array.isArray(value) ? value.slice(0, max) : [];

function sanitizeTurn(turn, { allowedCgIds = [] } = {}) {
  if (!turn || typeof turn !== 'object') throw new Error('모델 응답이 비어 있습니다.');
  const dm = turn.director || {};
  const allowedIntervention = new Set(['none','light','medium','scheduled','aftermath']);
  const allowedBeat = new Set(['routine','encounter','friction','choice','payoff_opportunity','payoff','aftermath','scheduled','investigation','combat']);
  const allowedEventKind = new Set(['none','social','academic','rumor','request','rivalry','investigation','politics','comedy','relationship','combat','world']);
  const allowedCallbackPhase = new Set(['none','friction','pressure','payoff_opportunity','payoff','aftermath']);
  turn.director = {
    intervention: allowedIntervention.has(dm?.intervention) ? dm.intervention : 'light',
    beat: allowedBeat.has(dm?.beat) ? dm.beat : (turn.importance === 'routine' ? 'routine' : 'encounter'),
    event_kind: allowedEventKind.has(dm?.event_kind) ? dm.event_kind : 'none',
    spotlight_keys: arrays(dm?.spotlight_keys,4).filter(key=>REGISTERED_SPEAKER_KEYS.has(key)),
    callback_key: String(dm?.callback_key || '').slice(0,80) || null,
    callback_phase: allowedCallbackPhase.has(dm?.callback_phase) ? dm.callback_phase : 'none',
    callback_note: String(dm?.callback_note || '').slice(0,280) || null,
    reason: String(dm?.reason || '장면 흐름 유지').slice(0,280),
  };
  turn.choices = arrays(turn.choices, 3);
  const sceneCap = turn.importance === 'routine' ? 8 : turn.importance === 'important' ? 14 : 18;
  turn.scene = arrays(turn.scene, sceneCap).map((item) => {
    if (item?.kind !== 'dialogue') {
      return { ...item, speaker_key: null, speaker_name: null, expression: null, emotion_intensity:null, emotion_confidence:null, emotion_reason:null };
    }
    const key = item?.speaker_key && REGISTERED_SPEAKER_KEYS.has(item.speaker_key) ? item.speaker_key : null;
    return {
      ...item,
      speaker_key: key,
      speaker_name: key ? (item.speaker_name || CHARACTER_REGISTRY[key]) : (item.speaker_name || 'NPC'),
      expression: EXPRESSIONS.has(item?.expression) ? item.expression : 'default',
      emotion_intensity: clamp(item?.emotion_intensity ?? 0.5, 0, 1),
      emotion_confidence: clamp(item?.emotion_confidence ?? 0.65, 0, 1),
      emotion_reason: String(item?.emotion_reason || '').slice(0,220) || null,
    };
  });

  const allowedCg = new Set(Array.isArray(allowedCgIds) ? allowedCgIds : []);
  if (!turn.cg_id || !allowedCg.has(turn.cg_id)) turn.cg_id = null;

  const d = turn.state_delta || {};
  d.advance_minutes = clamp(d.advance_minutes, 0, 1440);
  d.fatigue_delta = clamp(d.fatigue_delta, -10, 10);
  d.gold_delta = clamp(d.gold_delta, -10000, 10000);
  d.relationship_changes = arrays(d.relationship_changes, 10)
    .filter((row) => REGISTERED_SPEAKER_KEYS.has(row?.npc_key))
    .map(row => ({
      ...row,
      cause: String(row?.cause || '').slice(0,260) || null,
      expression: String(row?.expression || '').slice(0,260) || null,
      followup: String(row?.followup || '').slice(0,260) || null,
    }));
  d.intimacy_changes = arrays(d.intimacy_changes, 6).filter((row) => REGISTERED_SPEAKER_KEYS.has(row?.npc_key));
  d.stat_progress = arrays(d.stat_progress, 4);
  d.skill_experience = arrays(d.skill_experience, 12);
  d.items_add = arrays(d.items_add, 12);
  d.items_remove = arrays(d.items_remove, 12);
  d.active_events_add = arrays(d.active_events_add, 8);
  d.active_events_remove = arrays(d.active_events_remove, 8);
  d.completed_events_add = arrays(d.completed_events_add, 8);
  d.pc_knowledge_add = arrays(d.pc_knowledge_add, 10);
  d.memories_add = arrays(d.memories_add, 12).map(row => ({
    ...row,
    importance:clamp(row?.importance,1,5),
    secret_level:clamp(row?.secret_level,0,5),
    subject:String(row?.subject || '').slice(0,120) || null,
    source:String(row?.source || '').slice(0,200) || null,
    confidence:row?.confidence == null ? null : clamp(row.confidence,0,1),
    status:String(row?.status || '').slice(0,40) || null,
  }));
  d.scheduled_events_add = arrays(d.scheduled_events_add, 8).map(row => ({...row, participants:arrays(row?.participants,12).filter(key=>REGISTERED_SPEAKER_KEYS.has(key)), importance:clamp(row?.importance,1,5)}));
  d.scheduled_events_complete = arrays(d.scheduled_events_complete, 8).map(String);
  d.hooks_add = arrays(d.hooks_add, 8).map(row => ({
    ...row,
    source_npc_key: row?.source_npc_key && REGISTERED_SPEAKER_KEYS.has(row.source_npc_key) ? row.source_npc_key : null,
    importance: clamp(row?.importance,1,5),
  }));
  d.hooks_update = arrays(d.hooks_update, 8);
  d.npc_state_updates = arrays(d.npc_state_updates, 12).filter((row) => REGISTERED_SPEAKER_KEYS.has(row?.npc_key));
  turn.state_delta = d;
  turn.scene_summary = String(turn.scene_summary || '').slice(0,1200);
  return turn;
}

function usageSummary(model, usage = {}) {
  const input = Number(usage.input_tokens || 0);
  const output = Number(usage.output_tokens || 0);
  const inputDetails = usage.input_tokens_details || {};
  const outputDetails = usage.output_tokens_details || {};
  const cached = Number(inputDetails.cached_tokens || 0);
  const cacheWrite = Number(inputDetails.cache_write_tokens || inputDetails.cache_creation_tokens || 0);
  const reasoning = Number(outputDetails.reasoning_tokens || 0);
  const uncached = Math.max(0, input - cached - cacheWrite);
  const price = PRICES[model] || PRICES[model?.includes('luna') ? 'gpt-5.6-luna' : model?.includes('sol') ? 'gpt-5.6-sol' : 'gpt-5.6-terra'];
  const usd = (uncached * price.input + cached * price.cached + cacheWrite * price.input * 1.25 + output * price.output) / 1_000_000;
  const cacheHitRate = input > 0 ? cached / input : 0;
  return {
    input_tokens: input,
    output_tokens: output,
    reasoning_tokens: reasoning,
    cached_tokens: cached,
    cache_write_tokens: cacheWrite,
    uncached_input_tokens: uncached,
    cache_hit_rate: Number(cacheHitRate.toFixed(4)),
    estimated_usd: Number(usd.toFixed(6)),
    cold_cache: input > 12000 && cached < input * 0.15,
  };
}
// ===== END utils.js =====

// ===== VERCEL HANDLER =====
export const config = { maxDuration: 300 };

const json = (res, status, payload) => res.status(status).json(payload);

export default async function handler(req, res) {
  if (req.method !== 'POST') return json(res, 405, { error: 'POST만 지원합니다.' });
  if (!process.env.OPENAI_API_KEY) return json(res, 503, { error: 'Vercel 환경변수 OPENAI_API_KEY가 없습니다.', code: 'NO_API_KEY' });
  const requiredToken = process.env.LUMENSIA_ACCESS_TOKEN;
  if (requiredToken && req.headers['x-lumensia-token'] !== requiredToken) {
    return json(res, 401, { error: '루멘시아 접속 토큰이 없거나 틀렸습니다.', code: 'BAD_ACCESS_TOKEN' });
  }

  try {
    const body = typeof req.body === 'string' ? JSON.parse(req.body) : (req.body || {});
    const action = String(body.action || '').trim();
    if (!action) return json(res, 400, { error: '행동 입력이 비어 있습니다.' });
    if (action.length > 5000) return json(res, 400, { error: '한 번의 입력은 5,000자 이하로 줄여주세요.' });

    const saveState = body.saveState && typeof body.saveState === 'object' ? body.saveState : {};
    const recentTurns = Array.isArray(body.recentTurns) ? body.recentTurns.slice(-8) : [];
    const availableCgIds = Array.isArray(body.availableCgIds) ? body.availableCgIds.slice(0, 100) : [];
    const inputMode = body.inputMode === 'meta' ? 'meta' : 'game';
    const directorPlan = buildDirectorContext({ saveState, recentTurns, action, inputMode });
    const proReasoning = Boolean(body.proReasoning);
    const route = chooseModel({
      mode: body.modelMode,
      action,
      saveState,
      proReasoning,
      forceTerra: Boolean(body.forceTerra),
    });
    const effort = reasoningFor(route.tier, body.reasoningEffort, proReasoning);
    const proseLength = ['short', 'medium', 'long'].includes(body.proseLength) ? body.proseLength : 'medium';
    const pcAge = Number(saveState?.pc?.age || 0);
    const adultEligible = Number.isFinite(pcAge) && pcAge >= 18;
    const adultActive = Boolean(body.adultMode) && adultEligible;

    const client = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY,
      timeout: 105_000,
      maxRetries: 0,
    });
    const reasoning = { effort };
    if (proReasoning) reasoning.mode = 'pro';

    const maxOutput = proReasoning
      ? 6200
      : route.tier === 'terra'
        ? (proseLength === 'long' ? 5200 : proseLength === 'short' ? 2200 : 3600)
        : (proseLength === 'long' ? 3600 : proseLength === 'short' ? 1600 : 2400);

    const response = await client.responses.parse({
      model: route.model,
      store: false,
      instructions: buildInstructions(),
      input: buildTurnInput({
        action,
        saveState,
        recentTurns,
        rollingSummary: body.rollingSummary || '',
        availableCgIds,
        adultMode: adultActive,
        adultEligible,
        proseLength,
        inputMode,
      }),
      reasoning,
      max_output_tokens: maxOutput,
      prompt_cache_key: process.env.OPENAI_PROMPT_CACHE_KEY || 'lumensia-v1.4.7-event-director-v1',
      prompt_cache_retention: '24h',
      text: {
        verbosity: proseLength === 'long' ? 'high' : proseLength === 'short' ? 'low' : 'medium',
        format: zodTextFormat(TurnSchema, 'lumensia_turn_v146'),
      },
    });

    if (!response.output_parsed) {
      return json(res, 502, { error: '구조화된 게임 응답을 받지 못했습니다.', request_id: response._request_id });
    }

    let turn = sanitizeTurn(response.output_parsed, { allowedCgIds: availableCgIds });
    if (!adultActive && turn?.state_delta) turn.state_delta.intimacy_changes = [];
    if (inputMode === 'meta') {
      turn.director = { intervention:'none', beat:'routine', event_kind:'none', spotlight_keys:[], callback_key:null, callback_phase:'none', callback_note:null, reason:'META freeze' };
      turn.importance = 'routine';
      turn.cg_id = null;
      turn.choices = [];
      turn.scene = (turn.scene || []).map(item => ({
        ...item,
        kind:'narration',
        speaker_key:null,
        speaker_name:null,
        expression:null,
        emotion_intensity:null,
        emotion_confidence:null,
        emotion_reason:null,
      }));
      turn.state_delta = {
        advance_minutes:0, new_location:null, pc_status:null, fatigue_delta:0, gold_delta:0,
        relationship_changes:[], intimacy_changes:[], stat_progress:[], skill_experience:[],
        items_add:[], items_remove:[], active_events_add:[], active_events_remove:[],
        completed_events_add:[], pc_knowledge_add:[], memories_add:[],
        scheduled_events_add:[], scheduled_events_complete:[], hooks_add:[], hooks_update:[],
        npc_state_updates:[],
      };
    } else {
      turn = resolveTurnEmotions(turn, saveState);
    }
    return json(res, 200, {
      turn,
      route: {
        model: route.model,
        tier: route.tier,
        reason: route.reason,
        reasoning_effort: effort,
        reasoning_mode: proReasoning ? 'pro' : 'standard',
        max_output_tokens: maxOutput,
        adult_active: adultActive,
        input_mode: inputMode,
        director_plan: {
          intervention: directorPlan.intervention,
          objective: directorPlan.objective,
          choice_due: directorPlan.choiceDue,
          cross_department_due: directorPlan.crossDue,
          payoff_due: directorPlan.payoffDue,
          candidates: (directorPlan.candidates || []).slice(0,4).map(x=>({key:x.key,name:x.name,score:x.score})),
          callbacks: (directorPlan.callbacks || []).slice(0,4).map(x=>({key:x.key,status:x.status,age:x.age})),
        },
      },
      usage: usageSummary(route.model, response.usage),
      request_id: response._request_id || null,
      server_version: '0.5.6',
    });
  } catch (error) {
    console.error(error);
    const message = String(error?.message || '');
    const timeoutLike =
      error?.name === 'APIConnectionTimeoutError' ||
      (error?.name === 'APIConnectionError' && /timed? ?out/i.test(message)) ||
      /timed? ?out/i.test(message);

    const status = timeoutLike
      ? 504
      : (error?.status && Number.isInteger(error.status) ? error.status : 500);

    return json(res, status, {
      error: timeoutLike
        ? 'OpenAI 응답이 105초를 넘겨 중단했습니다. 게임 상태는 변경되지 않았습니다. 같은 행동을 다시 시도해 주세요.'
        : (error?.message || 'API 호출 중 오류가 발생했습니다.'),
      code: timeoutLike ? 'OPENAI_TIMEOUT' : (error?.code || 'UNKNOWN'),
      request_id: error?.request_id || null,
    });
  }
}
